const items = [];
const conversationId = $json.conversationId || 'unknown';

// Process all binary data files
const binaryData = $input.item.binary || {};

for (const [key, value] of Object.entries(binaryData)) {
  if (value && value.data) {
    const tempPath = `/tmp/${Date.now()}_${value.fileName}`;

    items.push({
      json: {
        conversationId: conversationId,
        originalName: value.fileName,
        mimeType: value.mimeType,
        size: value.fileSize || 0,
        tempPath: tempPath,
        binaryPropertyName: key,
        uploadedAt: new Date().toISOString()
      },
      binary: {
        file: value
      }
    });
  }
}

return items;

// Aggregate all file metadata for response
const files = $input.all();

return {
  success: true,
  uploadedFiles: files.map(item => ({
    originalName: item.json.originalName,
    mimeType: item.json.mimeType,
    size: item.json.size,
    tempPath: item.json.tempPath,
    binaryPropertyName: item.json.binaryPropertyName
  })),
  count: files.length,
  conversationId: files[0]?.json.conversationId
};
